function even(n: int): bool
  requires n >= 0
{
  if n == 0 then true else !even(n-1)
}

method is_even(n: int) returns (r: bool)
  ensures r <==> even(n);
{
  var i: int := 0;
  r := true;

  while i < n
    invariant 0 <= i <= n;
    invariant r <==> even(i);
  {
    r := !r;
    i := i + 1;
  }
}

